#pragma once

#include <cstdint>

namespace hybrid {

enum class AarSize : uint8_t
{
  Bits32 = 2,
  Bits64 = 3,
  Bits128 = 4,
};

constexpr auto regno_csr(uint16_t csr) -> uint16_t { return csr; }
constexpr auto regno_gpr(uint16_t i) -> uint16_t { return 0x1000u + i; }
constexpr auto regno_fpr(uint16_t i) -> uint16_t { return 0x1020u + i; }
constexpr auto regno_vector(uint16_t i) -> uint16_t { return 0x1040u + i; }

constexpr auto access_register_command(uint16_t regno, AarSize size, bool write,
                                       bool postexec = false) -> uint32_t
{
  uint32_t cmd = 0;
  cmd |= (uint32_t(size) & 0x7u) << 20;
  if (postexec) cmd |= 1u << 18;
  cmd |= 1u << 17;
  if (write) cmd |= 1u << 16;
  cmd |= regno;
  return cmd;
}

// DMI register addresses (RISC-V Debug Spec table 3.1 / DM register map).
inline constexpr uint8_t kDmiData0 = 0x04u;
inline constexpr uint8_t kDmiData1 = 0x05u;
inline constexpr uint8_t kDmiAbstractcs = 0x16u;
inline constexpr uint8_t kDmiCommand = 0x17u;

// abstractcs fields (Debug Spec 3.14.6).
inline constexpr uint32_t kAbstractcsBusy = 1u << 12;
inline constexpr uint32_t kAbstractcsCmderrMask = 0x7u << 8;

}  // namespace hybrid

// Program Buffer execution helpers for the RISC-V Debug Module.
//
// Follows the same duck-typed template pattern as dmi_poll.hpp so that
// resume_driver.hpp can include this header without a circular dependency.
// Bus type requirement: write(uint8_t reg, uint32_t val) and
//                       read(uint8_t reg) -> uint32_t.
//
// Debug Spec references: section 3.6 (Program Buffer), table 3.1 (DMI),
// section 3.7.1.3 (Abstract Command - Access Register).

#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/dmi_poll.hpp"

#include <array>
#include <cstdint>
#include <span>
#include <stdexcept>
#include <string>

namespace hybrid {

// DMI address of the first Program Buffer register (progbuf0..progbuf15).
inline constexpr uint8_t kProgbuf0 = 0x20u;

// Max payload instructions: 16 total slots minus 1 reserved for the
// mandatory ebreak that terminates execution.
inline constexpr std::size_t kProgbufMaxInsns = 15u;

// Standard ebreak encoding (funct12=1, opcode=SYSTEM).
inline constexpr uint32_t kEbreak = 0x00100073u;

// "Execute Program Buffer only" command (Debug Spec table 3.1):
//   cmdtype  = 0 (Access Register)
//   aarsize  = Bits64 (3) - ignored by DM when transfer=0, set for consistency
//   postexec = 1 (bit 18)
//   transfer = 0 (bit 17 NOT set) - skip register I/O, only run progbuf
//   write    = 0 (irrelevant when transfer=0)
//   regno    = 0 (irrelevant when transfer=0)
inline constexpr uint32_t kExecProgbufCmd =
    (uint32_t(AarSize::Bits64) & 0x7u) << 20 | (1u << 18);

// Encode `vsetvl rd, rs1, rs2` (RVV 1.0 section 6.2, funct7=1000000).
// Tier-B restore: stage vl in rs1 and vtype in rs2 via Abstract Commands,
// then branch-free-restore both in one Program Buffer execution.
inline constexpr uint32_t encode_vsetvl(uint8_t rd, uint8_t rs1, uint8_t rs2)
{
    return (0b1000000u << 25)
         | ((uint32_t(rs2) & 0x1Fu) << 20)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | (0b111u << 12)
         | ((uint32_t(rd)  & 0x1Fu) << 7)
         | 0x57u;  // OP-V opcode
}

// Encode `csrrw rd, csr, rs1` (SYSTEM opcode, funct3=001).
// Tier-A PB fallback: stage the CSR value in rs1 via Abstract Command,
// then write it to a CSR that the DM cannot reach via abstract access.
inline constexpr uint32_t encode_csrrw(uint8_t rd, uint16_t csr, uint8_t rs1)
{
    return ((uint32_t(csr) & 0xFFFu) << 20)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | (0b001u << 12)
         | ((uint32_t(rd)  & 0x1Fu) << 7)
         | 0x73u;  // SYSTEM opcode
}

// Encode `vle8.v vd, (rs1)` - unit-stride vector load, EEW=8 (RVV 1.0 sec 7.4).
// Fields: vm=1 (unmasked, bit 25), width=000, mop=00, mew=0, nf=000,
// lumop=00000, opcode LOAD-FP=0x07. PB V-regfile reload sweeps v0..v31 from
// the shared scratch region after a vsetvl to e8/m1.
inline constexpr uint32_t encode_vle8_v(uint8_t vd, uint8_t rs1)
{
    return (1u << 25)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | ((uint32_t(vd)  & 0x1Fu) << 7)
         | 0x07u;  // LOAD-FP opcode
}

// Encode `vse8.v vs3, (rs1)` - unit-stride vector store, EEW=8. Mirror of
// encode_vle8_v with opcode STORE-FP=0x27. PB V-regfile dump sweeps v0..v31
// back to the shared scratch region at drain.
inline constexpr uint32_t encode_vse8_v(uint8_t vs3, uint8_t rs1)
{
    return (1u << 25)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | ((uint32_t(vs3) & 0x1Fu) << 7)
         | 0x27u;  // STORE-FP opcode
}

// Encode `addi rd, rs1, imm12` (OP-IMM opcode 0x13, funct3=000). The batched
// V-data sweep advances the scratch base pointer x7 by one register-span
// between transfers WITHIN a Program-Buffer execution, so the per-register
// abstract x7 write disappears. imm12 is a signed 12-bit field (-2048..2047).
inline constexpr uint32_t encode_addi(uint8_t rd, uint8_t rs1, int32_t imm12)
{
    return ((uint32_t(imm12) & 0xFFFu) << 20)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | ((uint32_t(rd)  & 0x1Fu) << 7)
         | 0x13u;  // OP-IMM opcode (funct3=000)
}

// Encode `lwu rd, imm12(rs1)` (LOAD opcode 0x03, funct3=110 for 32-bit ZERO-
// extend, I-type). L2C MMIO registers must be accessed less than 8 bytes at a
// time (DS220 11.8.3), so the L2C config read-back loads a word. lwu (not lw)
// so a 32-bit register value does not sign-extend into the upper bits of the
// 64-bit GPR it lands in.
inline constexpr uint32_t encode_lwu(uint8_t rd, uint8_t rs1, int32_t imm12)
{
    return ((uint32_t(imm12) & 0xFFFu) << 20)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | (0b110u << 12)
         | ((uint32_t(rd)  & 0x1Fu) << 7)
         | 0x03u;  // LOAD opcode
}

// Encode `sw rs2, imm12(rs1)` (STORE opcode 0x23, funct3=010 for 32-bit,
// S-type: imm[11:5] -> bits 31:25, imm[4:0] -> bits 11:7). L2C MMIO registers
// must be accessed less than 8 bytes at a time (DS220 11.8.3), so the L2C
// config restore writes a word. All documented L2C control bits live in the
// low 32 bits.
inline constexpr uint32_t encode_sw(uint8_t rs2, uint8_t rs1, int32_t imm12)
{
    const uint32_t imm = uint32_t(imm12) & 0xFFFu;
    return ((imm >> 5) & 0x7Fu) << 25
         | ((uint32_t(rs2) & 0x1Fu) << 20)
         | ((uint32_t(rs1) & 0x1Fu) << 15)
         | (0b010u << 12)
         | ((imm & 0x1Fu) << 7)
         | 0x23u;  // STORE opcode
}

// Write insns[0..n-1] to progbuf0..n-1 and kEbreak to progbuf[n].
// Clears any sticky abstractcs.cmderr (W1C), issues kExecProgbufCmd, polls
// until abstractcs.busy clears, then verifies cmderr stayed clear.
//
// Throws std::runtime_error if insns.size() > kProgbufMaxInsns, if the poll
// times out, or if the DM raises cmderr during execution. No caller has a
// legitimate reason to silently continue on PB failure - the hart state
// would be partially restored / partially drained, which is worse than
// surfacing the fault.
template<typename Bus>
inline void exec_progbuf(Bus& bus, std::span<const uint32_t> insns)
{
    if (insns.size() > kProgbufMaxInsns)
        throw std::runtime_error(
            "exec_progbuf: too many instructions ("
            + std::to_string(insns.size()) + " > "
            + std::to_string(kProgbufMaxInsns) + ")");

    for (std::size_t i = 0; i < insns.size(); ++i)
        bus.write(static_cast<uint8_t>(kProgbuf0 + i), insns[i]);
    bus.write(static_cast<uint8_t>(kProgbuf0 + insns.size()), kEbreak);

    if ((bus.read(kDmiAbstractcs) & kAbstractcsCmderrMask) != 0u)
        bus.write(kDmiAbstractcs, kAbstractcsCmderrMask);

    bus.write(kDmiCommand, kExecProgbufCmd);
    poll_until_clear(bus, kDmiAbstractcs, kAbstractcsBusy, "exec_progbuf busy");

    const uint32_t cmderr = bus.read(kDmiAbstractcs) & kAbstractcsCmderrMask;
    if (cmderr != 0u)
        throw std::runtime_error(
            "exec_progbuf: PB execution raised cmderr="
            + std::to_string(cmderr >> 8));
}

// vtype encoding for e8, m8, ta, ma (vsew=000, vlmul=011, vta=1, vma=1). The
// V-data sweep uses LMUL=8 so one vle8.v/vse8.v moves a whole group of 8
// registers (8*vlenb byte-elements, vl=8*vlenb) in a single instruction.
inline constexpr uint32_t kVtypeE8M8 = 0xC3u;

// Abstract-command write of a 64-bit value to Debug Module register `regno`
// (GPR/CSR/FPR): DATA0/DATA1 + Access-Register(write) + busy-poll. Free
// function so ResumeDriver, StateDrain, and the V-data sweep share one copy.
template<typename Bus>
inline void write_register_abstract(Bus& bus, uint16_t regno, uint64_t value)
{
    bus.write(kDmiData0, static_cast<uint32_t>(value & 0xffffffffu));
    bus.write(kDmiData1, static_cast<uint32_t>((value >> 32) & 0xffffffffu));
    bus.write(kDmiCommand,
              access_register_command(regno, AarSize::Bits64, /*write=*/true));
    poll_until_clear(bus, kDmiAbstractcs, kAbstractcsBusy,
                     "write_register_abstract");
}

// Sweep all 32 V data registers between the hart regfile and the vlenb-packed
// scratch region via the Program Buffer. load=true issues vle8.v
// (scratch -> regfile, on resume); load=false issues vse8.v (regfile ->
// scratch, at drain). The leading vsetvl to e8/m8 sets vl=8*vlenb and forces
// vstart=0, so one unit-stride access covers a whole LMUL=8 group of 8
// registers. Uses x5/x6 (vsetvl operands) and x7 (group base pointer) as
// scratch. `vlenb` is the runtime per-register width; the scratch must be
// packed at vlenb stride (stage_v_to_scratch) so each 8-register group is
// contiguous.
template<typename Bus>
inline void pb_v_data_sweep(Bus& bus, uint64_t scratch_gpa, uint64_t vlenb,
                            bool load)
{
    // The scratch holds v0..v31 packed contiguously at vlenb stride (see
    // stage_v_to_scratch), so 8 consecutive registers form one LMUL=8 group.
    // One vle8.v/vse8.v then moves a whole group (8*vlenb contiguous bytes,
    // vl=8*vlenb) and all 32 registers transfer in 4 grouped ops -- whose 4
    // (transfer; addi) pairs fit in a SINGLE Program-Buffer execution. Each PB
    // execution is one halted-hart DM round-trip (~1000 sim cycles in the
    // busy-poll), so this is the floor: one vsetvl + one grouped execution. The
    // register bytes never cross DMI; they ride the shared mmap.
    constexpr unsigned     kRegsPerGroup   = 8;  // LMUL=8
    // kVtypeE8M8's vlmul field (bits 2:0) must encode this LMUL, so one grouped
    // vle8.v/vse8.v really covers kRegsPerGroup registers (integer LMUL=1<<vlmul;
    // 0xC3 & 7 == 3 -> LMUL 8).
    static_assert((1u << (kVtypeE8M8 & 0x7u)) == kRegsPerGroup,
                  "kVtypeE8M8 must encode LMUL = kRegsPerGroup");
    constexpr std::size_t  kGroupSweepInsns = (32 / kRegsPerGroup) * 2;  // (ld;addi)*4
    static_assert(kGroupSweepInsns <= kProgbufMaxInsns,
                  "the grouped sweep must fit one Program Buffer execution");
    const uint64_t group_bytes = static_cast<uint64_t>(kRegsPerGroup) * vlenb;
    if (group_bytes > 2047)  // addi imm12 is signed 12-bit; max 8*128 = 1024
        throw std::runtime_error(
            "pb_v_data_sweep: 8*vlenb exceeds the addi imm12 range");

    // vsetvl to e8/m8 with AVL = 8*vlenb sets vl = VLMAX = 8*vlenb (one
    // byte-element per lane across the whole group) and forces vstart = 0.
    write_register_abstract(bus, regno_gpr(5), group_bytes);  // AVL
    write_register_abstract(bus, regno_gpr(6), kVtypeE8M8);   // e8, m8, ta, ma
    const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
    exec_progbuf(bus, std::span<const uint32_t>{pb_vsetvl});

    // Base pointer x7 staged once; the in-buffer addi advances it one group at
    // a time. The group base register must be LMUL-aligned: v0/v8/v16/v24.
    write_register_abstract(bus, regno_gpr(7), scratch_gpa);
    const uint32_t addi_step =
        encode_addi(7, 7, static_cast<int32_t>(group_bytes));
    std::array<uint32_t, kGroupSweepInsns> group_sweep{};
    std::size_t n = 0;
    for (uint8_t g = 0; g < 32; g += kRegsPerGroup) {
        group_sweep[n++] = load ? encode_vle8_v(g, 7) : encode_vse8_v(g, 7);
        group_sweep[n++] = addi_step;  // last group's addi is harmless dead work
    }
    exec_progbuf(bus, std::span<const uint32_t>{group_sweep.data(), n});
}

}  // namespace hybrid

// Unit tests for hybrid/program_buffer.hpp.
// Pure compile-time and recording-bus tests -- no SystemC, no hardware.

#include "hybrid/program_buffer.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <array>
#include <cstdint>
#include <stdexcept>
#include <vector>

using namespace hybrid;

// ---- Recording DmiBus stub -------------------------------------------------
// Captures all writes; returns configurable values per register address.
struct RecBus
{
    struct Op { uint8_t reg; uint32_t val; };

    std::vector<Op> writes;
    // Per-register read sequences: each call pops the front value.
    // If the list is empty, returns 0.
    std::map<uint8_t, std::vector<uint32_t>> read_seq;

    void write(uint8_t reg, uint32_t val) { writes.push_back({reg, val}); }

    uint32_t read(uint8_t reg)
    {
        auto it = read_seq.find(reg);
        if (it == read_seq.end() || it->second.empty()) return 0u;
        uint32_t v = it->second.front();
        it->second.erase(it->second.begin());
        return v;
    }
};

// ---- kExecProgbufCmd constant tests ----------------------------------------

TEST_CASE("kExecProgbufCmd: postexec=1, transfer=0, cmdtype=AccessRegister")
{
    CHECK(((kExecProgbufCmd >> 18) & 1u) == 1u);   // postexec set
    CHECK(((kExecProgbufCmd >> 17) & 1u) == 0u);   // transfer NOT set (unlike access_register_command)
    CHECK(((kExecProgbufCmd >> 24) & 0xFFu) == 0u); // cmdtype = AccessRegister (0)
}

TEST_CASE("kEbreak encodes a standard ebreak instruction")
{
    // ebreak = funct12=000000000001, rs1=0, funct3=0, rd=0, opcode=SYSTEM(0x73)
    CHECK(kEbreak == 0x00100073u);
}

TEST_CASE("kProgbufMaxInsns leaves room for ebreak")
{
    // 16 slots total (progbuf0..progbuf15); 15 for payload, 1 for ebreak
    CHECK(kProgbufMaxInsns == 15u);
    CHECK(kProgbuf0 == 0x20u);
}

// ---- Instruction encoder tests ---------------------------------------------

TEST_CASE("encode_vsetvl: known encodings")
{
    // vsetvl x0, t0, t1  (rd=0, rs1=5, rs2=6)
    // RVV 1.0: funct7=1000000, opcode=1010111(0x57), funct3=111
    // 1|000000|00110|00101|111|00000|1010111 = 0x8062F057
    CHECK(encode_vsetvl(0, 5, 6) == 0x8062F057u);

    // vsetvl x1, a0, a1  (rd=1, rs1=10, rs2=11)
    // 1|000000|01011|01010|111|00001|1010111 = 0x80B570D7
    CHECK(encode_vsetvl(1, 10, 11) == 0x80B570D7u);

    // vsetvl x0, x0, x0  (all-zero registers)
    // 1|000000|00000|00000|111|00000|1010111 = 0x80007057
    CHECK(encode_vsetvl(0, 0, 0) == 0x80007057u);
}

TEST_CASE("encode_csrrw: known encodings")
{
    // csrrw x0, mstatus(0x300), t0(x5)
    // [31:20]=0x300, [19:15]=5, [14:12]=001, [11:7]=0, [6:0]=0x73
    // = 0x30029073
    CHECK(encode_csrrw(0, 0x300, 5) == 0x30029073u);

    // csrrw x0, vstart(0x008), t1(x6)
    // [31:20]=0x008, [19:15]=6, [14:12]=001, [11:7]=0, [6:0]=0x73
    // = 0x00831073
    CHECK(encode_csrrw(0, 0x008, 6) == 0x00831073u);

    // csrrw x0, vxsat(0x009), t0(x5)
    // [31:20]=0x009, [19:15]=5, [14:12]=001, [11:7]=0, [6:0]=0x73
    // = 0x00929073
    CHECK(encode_csrrw(0, 0x009, 5) == 0x00929073u);
}

TEST_CASE("encode_vle8_v: known encodings (golden hex from riscv64-elf-as)")
{
    // vle8.v vd, (rs1): unit-stride load, EEW=8. vm=1, width=000, mop=00,
    // mew=0, nf=000, lumop=00000, opcode LOAD-FP=0x07. The single set upper
    // bit is vm at bit 25. Verified with `riscv64-elf-as -march=rv64gcv`.
    CHECK(encode_vle8_v(0, 7)  == 0x02038007u);   // vle8.v v0,(x7)
    CHECK(encode_vle8_v(3, 7)  == 0x02038187u);   // vle8.v v3,(x7)
    CHECK(encode_vle8_v(31, 7) == 0x02038F87u);   // vle8.v v31,(x7)
}

TEST_CASE("encode_vse8_v: known encodings (golden hex from riscv64-elf-as)")
{
    // vse8.v vs3, (rs1): unit-stride store, EEW=8. Same fields as vle8.v but
    // opcode STORE-FP=0x27. Verified with `riscv64-elf-as -march=rv64gcv`.
    CHECK(encode_vse8_v(0, 7)  == 0x02038027u);   // vse8.v v0,(x7)
    CHECK(encode_vse8_v(3, 7)  == 0x020381A7u);   // vse8.v v3,(x7)
    CHECK(encode_vse8_v(31, 7) == 0x02038FA7u);   // vse8.v v31,(x7)
}

TEST_CASE("encode_addi: known encodings (golden hex from riscv64-elf-as)")
{
    // addi rd, rs1, imm12: OP-IMM (0x13), funct3=000. The V-data sweep advances
    // the scratch base pointer x7 by one register-span between batched
    // transfers. Verified with `riscv64-elf-as -march=rv64gcv`.
    CHECK(encode_addi(7, 7, 128)  == 0x08038393u);  // addi x7,x7,128
    CHECK(encode_addi(7, 7, 64)   == 0x04038393u);  // addi x7,x7,64
    CHECK(encode_addi(5, 5, 2047) == 0x7FF28293u);  // addi x5,x5,2047 (max imm)
}

TEST_CASE("encode_sw: known encodings (golden hex from riscv64-elf-as)")
{
    // sw rs2, imm(rs1): STORE opcode 0x23, funct3=010 (32-bit, S-type: the
    // 12-bit immediate splits imm[11:5] into bits 31:25 and imm[4:0] into
    // 11:7). L2C MMIO registers must be accessed < 8 bytes at a time (DS220
    // 11.8.3), so the L2C config restore writes a word. Verified with
    // `riscv64-elf-as`.
    CHECK(encode_sw(5, 6, 8)     == 0x00532423u);  // sw x5,8(x6)
    CHECK(encode_sw(5, 6, 0)     == 0x00532023u);  // sw x5,0(x6)
    CHECK(encode_sw(31, 30, 2047) == 0x7FFF2FA3u); // sw x31,2047(x30) (max imm)
}

TEST_CASE("encode_lwu: known encodings (golden hex from riscv64-elf-as)")
{
    // lwu rd, imm(rs1): LOAD opcode 0x03, funct3=110 (32-bit, ZERO-extend,
    // I-type): a zero-extending word load, so a 32-bit L2C register read does
    // not sign-pollute the upper bits of the u64 it lands in. Verified with
    // `riscv64-elf-as`.
    CHECK(encode_lwu(5, 6, 8)    == 0x00836283u);  // lwu x5,8(x6)
    CHECK(encode_lwu(5, 6, 0)    == 0x00036283u);  // lwu x5,0(x6)
    CHECK(encode_lwu(7, 31, 240) == 0x0F0FE383u);  // lwu x7,240(x31)
}

// ---- exec_progbuf behavioral tests -----------------------------------------

TEST_CASE("exec_progbuf: single instruction - writes insn, ebreak, exec command")
{
    RecBus bus;
    const std::array<uint32_t, 1> insns{0xDEADBEEFu};
    exec_progbuf(bus, insns);

    // Writes (in order):
    //   progbuf0 = insn
    //   progbuf1 = ebreak
    //   command  = kExecProgbufCmd
    // (no pre-clear because bus returns 0 for abstractcs -> no cmderr)
    REQUIRE(bus.writes.size() == 3u);
    CHECK(bus.writes[0].reg == kProgbuf0);
    CHECK(bus.writes[0].val == 0xDEADBEEFu);
    CHECK(bus.writes[1].reg == kProgbuf0 + 1);
    CHECK(bus.writes[1].val == kEbreak);
    CHECK(bus.writes[2].reg == 0x17u);       // kDmiCommand
    CHECK(bus.writes[2].val == kExecProgbufCmd);
}

TEST_CASE("exec_progbuf: max instructions fills progbuf0..14, ebreak at progbuf15")
{
    RecBus bus;
    std::array<uint32_t, 15> insns{};
    for (uint32_t i = 0; i < 15; ++i) insns[i] = 0xAA000000u | i;

    exec_progbuf(bus, insns);

    // 15 payload writes + ebreak + exec command = 17 writes
    REQUIRE(bus.writes.size() == 17u);
    for (std::size_t i = 0; i < 15; ++i) {
        CHECK(bus.writes[i].reg == kProgbuf0 + i);
        CHECK(bus.writes[i].val == (0xAA000000u | i));
    }
    CHECK(bus.writes[15].reg == kProgbuf0 + 15u);
    CHECK(bus.writes[15].val == kEbreak);
    CHECK(bus.writes[16].reg == 0x17u);
    CHECK(bus.writes[16].val == kExecProgbufCmd);
}

TEST_CASE("exec_progbuf: 16 instructions throws - no bus writes happen")
{
    RecBus bus;
    std::array<uint32_t, 16> insns{};
    CHECK_THROWS_AS(exec_progbuf(bus, insns), std::runtime_error);
    CHECK(bus.writes.empty());
}

TEST_CASE("exec_progbuf: clears sticky cmderr before issuing exec command")
{
    RecBus bus;
    // abstractcs returns cmderr=set on the first read (pre-exec check),
    // then 0 thereafter (poll + final check)
    constexpr uint32_t kCmderrMask = 0x7u << 8;
    bus.read_seq[0x16u] = {kCmderrMask, 0u, 0u};

    const std::array<uint32_t, 1> insns{0x1u};
    exec_progbuf(bus, insns);

    // Expected writes: progbuf0=insn, progbuf1=ebreak,
    //                  abstractcs=kCmderrMask (W1C clear),
    //                  command=kExecProgbufCmd
    REQUIRE(bus.writes.size() == 4u);
    CHECK(bus.writes[2].reg == 0x16u);
    CHECK(bus.writes[2].val == kCmderrMask);
    CHECK(bus.writes[3].reg == 0x17u);
    CHECK(bus.writes[3].val == kExecProgbufCmd);
}

TEST_CASE("exec_progbuf: throws when cmderr set after execution")
{
    RecBus bus;
    constexpr uint32_t kCmderrMask = 0x7u << 8;
    // reads: [pre-exec cmderr check=0], [busy poll=0], [final cmderr check=set]
    bus.read_seq[0x16u] = {0u, 0u, kCmderrMask};

    const std::array<uint32_t, 1> insns{0x1u};
    CHECK_THROWS_AS(exec_progbuf(bus, insns), std::runtime_error);
}

TEST_CASE("exec_progbuf: polls while busy before returning")
{
    RecBus bus;
    constexpr uint32_t kBusy = 1u << 12;
    // abstractcs: no pre-cmderr, busy once, then clear, then no post-cmderr
    bus.read_seq[0x16u] = {0u, kBusy, 0u, 0u};

    const std::array<uint32_t, 1> insns{0x1u};
    CHECK_NOTHROW(exec_progbuf(bus, insns));
}

// ---- pb_v_data_sweep batching tests ----------------------------------------
// Each Program-Buffer execution is one halted-hart DM round-trip (~1000 sim
// cycles in the busy-poll), so the cost is the NUMBER of executions, not the
// bytes moved. The sweep batches (transfer; addi) pairs into each execution
// and advances the base pointer x7 with the in-buffer addi, so 32 registers
// cost ceil(32/7)=5 executions and ONE x7 abstract write -- instead of 32
// executions plus 32 per-register x7 writes.

namespace {
int count_exec_cmds(const RecBus& bus)
{
    int n = 0;
    for (const auto& w : bus.writes)
        if (w.reg == kDmiCommand && w.val == kExecProgbufCmd) ++n;
    return n;
}

int count_x7_abstract_writes(const RecBus& bus)
{
    int n = 0;
    for (const auto& w : bus.writes)
        if (w.reg == kDmiCommand && (w.val & 0xFFFFu) == regno_gpr(7)
            && ((w.val >> 16) & 1u) != 0u)
            ++n;
    return n;
}

bool progbuf_holds(const RecBus& bus, uint32_t insn)
{
    for (const auto& w : bus.writes)
        if (w.reg >= kProgbuf0 && w.reg <= kProgbuf0 + kProgbufMaxInsns
            && w.val == insn)
            return true;
    return false;
}

// Last 64-bit value staged into GPR g via an abstract write: data0/data1 are
// the two writes immediately preceding the command that targets regno_gpr(g)
// with the write bit set.
uint64_t staged_gpr_value(const RecBus& bus, uint16_t g)
{
    uint64_t v = 0;
    for (std::size_t i = 2; i < bus.writes.size(); ++i) {
        const auto& w = bus.writes[i];
        if (w.reg == kDmiCommand && (w.val & 0xFFFFu) == regno_gpr(g)
            && ((w.val >> 16) & 1u) != 0u)
            v = (uint64_t(bus.writes[i - 1].val) << 32) | bus.writes[i - 2].val;
    }
    return v;
}
}  // namespace

TEST_CASE("pb_v_data_sweep: LMUL=8 grouping loads all 32 registers in ONE "
          "PB execution from a single staged base")
{
    RecBus bus;
    constexpr uint64_t kScratch = 0x90000000ull;
    constexpr uint64_t kVlenb   = 64;          // VLEN=512
    constexpr uint64_t kGroup   = 8 * kVlenb;  // 512 bytes per LMUL=8 group

    pb_v_data_sweep(bus, kScratch, kVlenb, /*load=*/true);

    // 1 vsetvl execution + 1 grouped execution (all 4 groups fit) = 2
    // (33 before batching, 6 after addi-batching, 2 with LMUL grouping).
    CHECK(count_exec_cmds(bus) == 2);
    // Base staged once; the in-buffer addi advances it by one group (8*vlenb).
    CHECK(count_x7_abstract_writes(bus) == 1);
    CHECK(staged_gpr_value(bus, 7) == kScratch);
    CHECK(progbuf_holds(bus, encode_addi(7, 7, int32_t(kGroup))));

    // vsetvl operands: AVL=x5=8*vlenb (=VLMAX for m8) and vtype=x6=e8/m8.
    CHECK(staged_gpr_value(bus, 5) == kGroup);
    CHECK(staged_gpr_value(bus, 6) == kVtypeE8M8);

    // Exactly the 4 group bases are loaded (v0, v8, v16, v24); the other 28
    // registers ride inside their group, so they are NOT loaded directly.
    for (uint8_t g = 0; g < 32; g += 8)
        CHECK(progbuf_holds(bus, encode_vle8_v(g, 7)));
    CHECK(!progbuf_holds(bus, encode_vle8_v(1, 7)));
    CHECK(!progbuf_holds(bus, encode_vle8_v(9, 7)));
}

TEST_CASE("pb_v_data_sweep: load=false stores the 4 register groups via vse8.v")
{
    RecBus bus;
    pb_v_data_sweep(bus, 0x90000000ull, /*vlenb=*/64, /*load=*/false);

    for (uint8_t g = 0; g < 32; g += 8)
        CHECK(progbuf_holds(bus, encode_vse8_v(g, 7)));
    CHECK(count_exec_cmds(bus) == 2);
    CHECK(staged_gpr_value(bus, 6) == kVtypeE8M8);
}

// Encodes the RISC-V Debug Module "Access Register" Abstract Command (cmdtype=0)
// per the Debug Spec 1.0. Pure bit-manipulation; no SystemC dependency.

#include "hybrid/abstract_command.hpp"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

using hybrid::AarSize;
using hybrid::access_register_command;
using hybrid::regno_csr;
using hybrid::regno_fpr;
using hybrid::regno_gpr;
using hybrid::regno_vector;

TEST_CASE("regno helpers map to spec ranges")
{
  CHECK(regno_csr(0x000) == 0x0000);
  CHECK(regno_csr(0x7C0) == 0x07C0);
  CHECK(regno_gpr(0)     == 0x1000);
  CHECK(regno_gpr(31)    == 0x101F);
  CHECK(regno_fpr(0)     == 0x1020);
  CHECK(regno_fpr(31)    == 0x103F);
  CHECK(regno_vector(0)  == 0x1040);
  CHECK(regno_vector(31) == 0x105F);
}

TEST_CASE("write 64-bit GPR x10 = 0x1000 with transfer set")
{
  // cmdtype=0 (zero), aarsize=3 (64-bit) at [22:20], transfer=1 at [17],
  // write=1 at [16], regno=0x100A in [15:0].
  const auto cmd = access_register_command(regno_gpr(10), AarSize::Bits64,
                                           /*write=*/true);
  CHECK(((cmd >> 24) & 0xff) == 0u);                // cmdtype = AccessRegister
  CHECK(((cmd >> 20) & 0x7) == uint32_t(AarSize::Bits64));
  CHECK(((cmd >> 17) & 0x1) == 1u);                 // transfer
  CHECK(((cmd >> 16) & 0x1) == 1u);                 // write
  CHECK((cmd & 0xffff)      == 0x100Au);            // regno
}

TEST_CASE("read 64-bit CSR mstatus has write=0")
{
  const auto mstatus = 0x300u;
  const auto cmd = access_register_command(regno_csr(mstatus), AarSize::Bits64,
                                           /*write=*/false);
  CHECK(((cmd >> 16) & 0x1) == 0u);
  CHECK((cmd & 0xffff)      == mstatus);
  CHECK(((cmd >> 17) & 0x1) == 1u);                 // transfer always 1
}

TEST_CASE("32-bit aarsize encodes as 2")
{
  const auto cmd =
    access_register_command(regno_gpr(1), AarSize::Bits32, /*write=*/true);
  CHECK(((cmd >> 20) & 0x7) == 2u);
}

TEST_CASE("postexec=true sets bit 18, otherwise unset")
{
  const auto with_post = access_register_command(
    regno_gpr(0), AarSize::Bits64, /*write=*/false, /*postexec=*/true);
  const auto without = access_register_command(
    regno_gpr(0), AarSize::Bits64, /*write=*/false, /*postexec=*/false);
  CHECK(((with_post >> 18) & 0x1) == 1u);
  CHECK(((without   >> 18) & 0x1) == 0u);
}

